// ===================== AUDIT =====================

const sourceStatusCount = (status: SourceStatus) => sourceRegistry.filter((source) => source.status === status).length;

export const knowledgeAudit = {
  officialSourcesDiscovered: sourceRegistry.filter((source) => source.official).length,
  officialPdfsDiscovered: sourceRegistry.filter((source) => source.documentType.toLowerCase().includes("pdf")).length,
  officialPdfsParsed: sourceRegistry.filter((source) => source.documentType.toLowerCase().includes("pdf") && source.parsed).length,
  currentSources: sourceStatusCount("official_current"),
  historicalSources: sourceStatusCount("official_historical"),
  futureSources: sourceStatusCount("official_future"),
  restrictedSources: sourceStatusCount("access_restricted"),
  knowledgeClaims: evidenceRegistry.length,
  lessonsGenerated: knowledgeLessons.length,
  practicalScenarios: knowledgeLessons.filter((lesson) => lesson.scenario).length,
  quizQuestions: knowledgeQuestions.length,
  sourcesWithScreenshots: 0,
  unverifiedClaims: 0,
  notVerifiedTopics: knowledgeModules.filter((module) => module.status === "not_verified").length,
  lastVerified: verifiedOn,
};

export function sourceFor(id: string) {
  return sourceRegistry.find((source) => source.id === id);
}

export function evidenceFor(id: string) {
  return evidenceRegistry.find((evidence) => evidence.id === id);
}
